select `nd`.`nde_id_planilla` AS `nde_id_planilla`,`p`.`ppl_numero` AS `planilla`,`j`.`jub_correlativo` AS `id_jubilado`,concat(`j`.`jub_nombres`,' ',`j`.`jub_apellidos`) AS `nombre_completo`,`td`.`tde_tipo_descuento` AS `tipo_descuento`,`nd`.`nde_valor` AS `monto_descuento` from (((`apps_rpjepq`.`rpj_prc_nomina_descuento` `nd` join `apps_rpjepq`.`rpj_cat_parametro_planilla` `p` on(`p`.`ppl_correlativo` = `nd`.`nde_id_planilla`)) join `apps_rpjepq`.`rpj_mnt_jubilado` `j` on(`j`.`jub_correlativo` = `nd`.`nde_id_jubilado`)) join `apps_rpjepq`.`rpj_cat_tipo_descuento` `td` on(`td`.`tde_id` = `nd`.`nde_tipo_descuento`)) where `nd`.`nde_tipo_manejo` = 2
